from math import erf, exp, log, sqrt


def norm_cdf(z):
    return 0.5 * (1 + erf(z / sqrt(2)))


def bs_price(S, K, r, sigma, T, kind="call", q=0.0):
    """Black-Scholes price of a European option, dividend yield q."""
    if kind not in ("call", "put"):
        raise ValueError(f"kind must be 'call' or 'put', not {kind!r}")
    if T <= 0:                          # at expiry: intrinsic value
        return float(max(S - K, 0.0) if kind == "call" else max(K - S, 0.0))
    F = S * exp((r - q) * T)            # the forward
    D = exp(-r * T)                     # the discount factor
    if sigma <= 0:                      # no randomness: the forward payoff
        return D * (max(F - K, 0.0) if kind == "call" else max(K - F, 0.0))
    d1 = (log(S / K) + (r - q + sigma ** 2 / 2) * T) / (sigma * sqrt(T))
    d2 = d1 - sigma * sqrt(T)
    if kind == "call":
        return S * exp(-q * T) * norm_cdf(d1) - K * D * norm_cdf(d2)
    return K * D * norm_cdf(-d2) - S * exp(-q * T) * norm_cdf(-d1)

import numpy as np
from scipy.special import ndtr      # the normal cdf for arrays


def bs_price_vec(S, K, r, sigma, T, kind="call", q=0.0):
    """bs_price for NumPy arrays of strikes K and expiries T (T > 0)."""
    K = np.asarray(K, dtype=float)
    T = np.asarray(T, dtype=float)
    d1 = (np.log(S / K) + (r - q + sigma ** 2 / 2) * T) / (sigma * np.sqrt(T))
    d2 = d1 - sigma * np.sqrt(T)
    if kind == "call":
        return S * np.exp(-q * T) * ndtr(d1) - K * np.exp(-r * T) * ndtr(d2)
    if kind == "put":
        return K * np.exp(-r * T) * ndtr(-d2) - S * np.exp(-q * T) * ndtr(-d1)
    raise ValueError(f"kind must be 'call' or 'put', not {kind!r}")

