from pricers import bs_price as _right, norm_cdf as _ncdf
from math import exp as _exp, log as _log, sqrt as _sqrt

def wrong_q(S, K, r, sigma, T, kind='call', q=0.0):
    # q kept in d1 but missing from S * exp(-q * T)
    if T <= 0 or sigma <= 0:
        return _right(S, K, r, sigma, T, kind, q)
    d1 = (_log(S / K) + (r - q + sigma ** 2 / 2) * T) / (sigma * _sqrt(T))
    d2 = d1 - sigma * _sqrt(T)
    if kind == 'call':
        return S * _ncdf(d1) - K * _exp(-r * T) * _ncdf(d2)
    return K * _exp(-r * T) * _ncdf(-d2) - S * _ncdf(-d1)

def swapped(S, K, r, sigma, T, kind='call', q=0.0):
    # reads its arguments as (S, K, T, sigma, r)
    return _right(S, K, T, sigma, r, kind, q)

def no_guard(S, K, r, sigma, T, kind='call', q=0.0):
    # the textbook formula with no T = 0 or sigma = 0 case
    d1 = (_log(S / K) + (r - q + sigma ** 2 / 2) * T) / (sigma * _sqrt(T))
    d2 = d1 - sigma * _sqrt(T)
    if kind == 'call':
        return S * _exp(-q * T) * _ncdf(d1) - K * _exp(-r * T) * _ncdf(d2)
    return K * _exp(-r * T) * _ncdf(-d2) - S * _exp(-q * T) * _ncdf(-d1)

